template:
fn classify(val: i32) -> &'static str {
    match val {
        ⟦arm1_pat⟧ => "positive even",
        ⟦arm2_pat⟧ => "positive odd",
        _ => "other",
    }
}

fn main() {
    println!("{}", classify(4));
}

tests:
#[test]
fn test_classify() {
    assert_eq!(classify(4), "positive even");
    assert_eq!(classify(3), "positive odd");
    assert_eq!(classify(-2), "other");
    assert_eq!(classify(0), "other");
}
